o interact with PropertyGrid, you have to create your own "property class" (as described here). You can customise different parts and thus there are multiple solutions for what you want. As a first approach to your problem, here you have a code for propertyGrid1:Property curProperty = new Property();propertyGrid1.SelectedObject = curProperty;Where Property is defined by:public class Property{    private ColorDialog _dialog = new customColorDialogDialog();    public ColorDialog dialog    {        get { return _dialog; }        set { _dialog.ShowDialog(); }    }}class customColorDialogDialog : ColorDialog{}In this code, your color dialog (customColorDialogDialog) is triggered when clicking on the cell on the right hand side of the property name ("dialog").        public class ColorsProperty {            private List<Color> Colors = new List<Color>();            [CategoryAttribute("Barvy Pozadí"),                DisplayName("Gradient"),                DescriptionAttribute("Velikost rámu")            ]            public List<Color> Gradient {                get { return Colors; }                set { this.Colors = value; }            }            internal void AddColors(List<Color> colors) {                Colors = colors;            }        }            var colorsProp = new ColorsProperty();            colorsProp.AddColors(new List<Color>() {                Color.RoyalBlue,                Color.PaleTurquoise,                Color.MediumAquamarine,                Color.DarkGreen            });            propertyGrid1.SelectedObject = colorsProp;            propertyGrid1.ToolbarVisible = false;            propertyGrid1.HelpVisible = false;